import { StudioMotivation } from "../../../types/studio.types";
import { BudgetTierKey } from "../../../types/project.types";

/**
 * Rival plan contracts — the typed output of RivalBrain.
 *
 * Plans are pure data: generated by `planRivalWeek`, consumed by executor
 * systems in the same tick. Nothing in a plan mutates state directly; each
 * intent is either executed this tick by its owning system or expires.
 */

export interface RivalBidIntent {
  opportunityId: string;
  amount: number;
  /** >1 when relations/motivation escalate the bid past value. */
  spiteBoost: number;
}

export interface RivalTalentIntent {
  talentId: string;
  approach: "first_look" | "poach";
  reason: "hold" | "delay_response" | "strategic_fit" | "dynasty";
}

export interface RivalMnaIntent {
  targetId: string;
  kind: "opportunistic" | "strategic";
  maxBid: number;
}

export interface RivalSeriesIntent {
  projectId: string;
  decision: "renew" | "cancel" | "let_ride";
  reason: "anchor" | "prestige" | "ratings" | "economics";
}

export interface RivalPlan {
  rivalId: string;
  week: number;
  motivation: StudioMotivation;
  /** How this rival currently regards the player (from simMemory ledger). */
  stance: "hostile" | "rivalrous" | "neutral" | "deferential";
  /** Projects this rival intends to originate this week. */
  slate: {
    count: number;
    budgetTiers: BudgetTierKey[];
    preferredGenres: string[];
    preferTv: boolean;
  };
  /** Auction positions to take on open market opportunities. */
  bids: RivalBidIntent[];
  /** Marketing spend intents, keyed by project id (campaign attach) or "slate". */
  marketing: Record<string, number>;
  /** Optional release-window repositioning for a single project. */
  releaseIntent?: { projectId: string; targetWeek: number };
  strategic: {
    mna: RivalMnaIntent[];
    awardsPush: { projectId: string; spend: number }[];
  };
  talent: RivalTalentIntent[];
  series: RivalSeriesIntent[];
  /** Estimated industry marketing intensity contributed by this rival. */
  rivalSpend: number;
  /** Explainability trail — persisted to rival.intel and surfaced in UI. */
  reasons: string[];
}
